#!/usr/bin/env python3
"""Build a readable standalone shell script from the Python source."""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
HEADER = '''#!/usr/bin/env bash
# Generated by tools/build_installer.py. Edit src/resonite_frame.py instead.
# All installer code is included below; no GitHub credentials are used on Frame.
set -euo pipefail
command -v python3 >/dev/null || { echo 'python3 is required' >&2; exit 1; }
resonite_frame_tmp=$(mktemp -d)
trap 'rm -rf -- "$resonite_frame_tmp"' EXIT
cat >"$resonite_frame_tmp/resonite_frame.py" <<'RESONITE_FRAME_PYTHON_EOF'
'''
FOOTER = '''RESONITE_FRAME_PYTHON_EOF
python3 "$resonite_frame_tmp/resonite_frame.py" "$@"
'''
expected = HEADER + (ROOT/"src/resonite_frame.py").read_text() + FOOTER
destination = ROOT/"install.sh"
if "--check" in sys.argv:
    if not destination.is_file() or destination.read_text() != expected:
        raise SystemExit("install.sh is stale; run python3 tools/build_installer.py")
else:
    destination.write_text(expected)
    destination.chmod(0o755)
